import math
def compare_bounds(n, k):
    if n <= 2 * k:
        return "Constraint n>2k violated"
    b_w2 = (2**n) - math.comb(n, k)
    b_w4 = 2**(n - k)

    if b_w4 < b_w2:
        return f"2^{n-k} is strictly smaller than 2^n - C(n, k). W4 bound is dominant. (W4 < W2)"
    elif b_w4 == b_w2:
        return f"Bounds are equal. (W4 = W2)"
    else:
        return f"2^{n-k} is larger than 2^n - C(n, k). W2 bound is dominant. (W4 > W2)"

# Test cases where n > 2k
tests = [(4, 1), (6, 2), (8, 3)] 
for n, k in tests:
    print(f"Test (n={n}, k={k}): {compare_bounds(n, k)}")
